    /* ★ 2026-11-13 — **보수덧말**: 금액 바로 뒤에 붙은 「※ …」 조건을 **원문 그대로** 냅니다 (둘까지 · 200자).
       화면은 금액을 크게, 이 글을 아래 작은 글로 그립니다 (세중님 「4900만원만 넣고 아래 1년 만근 시 급여」).
         근로복지공단 인턴 「○ 월 1,761천원 수준(기본급 및 식대 포함)<br>※ 사무원 1일 6시간 근무 기준이며 근무시간에 따라 변동
                           <br>※ 전문자격에 해당하는 업무를 수행하는 경우 동일업무수행 공무직 및 기간제근로자 보수수준으로 책정」
       금액을 낸 때만 냅니다 — 「내규에 따름」에는 붙이지 않습니다. 다음 꼭지(끊곳)를 만나면 거기서 멈춥니다 */
