  봐('★ 「00명」 은 글 그대로', 영00.모집인원글?.작업치료사 === '00명');
  봐('★ 「00명」 을 숫자 0 으로 줄이지 않는다', !Object.keys(영00.모집인원).length);
  봐('★ 「00명」 근거에 까닭이 있다',
    /원문과 달라집니다/.test(String(영00.근거?.['모집인원글.작업치료사'] || '')));

  /* 한 자리 「0명」은 숫자 0 입니다 (위 견본 넷이 그렇습니다) */
  봐('한 자리 0명은 숫자 0',
    인원('1. 모집부분 - 물리치료센터 물리치료사 0명 2. 지원 자격 모집인원').물리치료사 === 0);

