  봐('307295 덧말에 사무원 기준 금액', /사무원 1일 6시간/.test(공단인턴.보수덧말 || '') && /1,761천원/.test(공단인턴.보수덧말 || ''));
  /* 대조 — 사무원 말이 없으면 전처럼 금액 + 덧말 */
