  /* 2026-11-21 규칙숙제 #6 — 제주대병원 307221(HS681749173 과 같은 공고) 「급여수준」 머리 칸 아래 (kordoc 글 그대로) */
  const 제주급여 = '## □ 계약기간 및 급여수준\n\n| 직종 | 직무 | 계약기간 | 급여수준 |\n| --- | --- | --- | --- |\n'
